{"name": "factorial_mod", "code": "
import math

def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Calculate factorial of n mod mod
    factorial = math.factorial(n)
    result = factorial % mod
    return float(result)
